// eslint-disable-next-line @typescript-eslint/no-namespace
namespace Gordic.Pok.WebClient {

    @Decorators.gcontent
    export class GPokHromadneStornoTab extends GContentBase {


        private gridStornoStep1: JQuery<HTMLElement>;
        private gridStornoStep2: JQuery<HTMLElement>;
        private gridStornoStep4: JQuery<HTMLElement>;
        pokDoklady: Gordic.Hpl.Interface.GPokDokladDto[];

        onContentReady() {

            var that = this;


            this.title = "Hromadné storno";
            this.setBreadcrumbs([{ caption: this.title, defaultAction: true }]);

            var gf = new Gordic.Data.GridFormat();
            gf.addTextColumn({
                name: "ixp",
                caption: "jres:31302005", //RC 31302005 : PID
                sortable: false
            });

            gf.addDateColumn({
                name: "wiz_datum",
                caption: "Datum odpárování"
            });

            const gridActionDetail = new GAction($.extend(true, Gordic.Eko.Action.actionDetail({
                run: function (ev, ctx) {
                    that.navigate("Gordic.Pok.WebClient.GPokDetailDokladuTab", {
                        ixp: ctx.cellInfo.data.ixp,
                        newPodani: false,
                        Id: "GPokDetailDokladu#"
                    });
                },
                enabled: true
            }), { name: "actDetail" }))


            this.navigate<Gordic.Eko.Components.TwoStepsOptions<Gordic.Hpl.Interface.GPokDokladDto>>(Gordic.Eko.Components.TwoStepsContent, {
                title: "Hromadné storno pokladních dokladů",
                gridFormat: gf,
                keys: "ixp",
                data: this.pokDoklady,
                indicatorType: "KPI",                
                firstStep: {
                    title: "Hromadné storno pokladních dokladů",
                    description: "Kontrola a doplnění důvodu před hromadným stornem",
                    gridTabTitle: "Vybrané pokladní doklady",
                    defaultAction: gridActionDetail,
                    form: new Gordic.Forms.Form({ name: "wizParams" }).addSection().addRow("Důvod").addField("gstringbox", { name: "reason", flag: Gordic.Prefabs.Field.Flags.required, validators: [new Gordic.Validators.Required()] }),
                    checkAction: (model, data) => {

                      
                        var view = new Gordic.Data.View(data, { key: "ixp" });
                        var ixpArray = data.map(function (d) { return d.ixp; });
                        let i = 0;

                        let def = $.Deferred();                        

                        ixpArray.forEach(function (x) {

                            that.isl.PokDoklad.seznamPermissions(rq => { return { ixp: x } }).get()
                                .done(function (data) {

                                    view.getDataRows(true).forEach(function (meta) {

                                        if (meta.data.ixp === x) {

                                            meta.data.wiz_kind = data.LzeStorno.value ? Gordic.Isl.GOperationResultKind.Success : Gordic.Isl.GOperationResultKind.Error;
                                            meta.data.wiz_txt_err = data.LzeStorno.message;
                                            meta.data.wiz_check = data.LzeStorno.value;


                                            //když můžu stornovat,tak si zkusím dotáhnout datum odpárování
                                            if (data.LzeStorno.value == true) {
                                                that.call("GetDatumOdparovani", { ixp: x })
                                                    .done(function (data) {
                                                        i = i + 1;

                                                        if (data.stav == 0) {
                                                            meta.data.wiz_kind = Gordic.Isl.GOperationResultKind.Success;
                                                            meta.data.wiz_datum = data.dat_odp;
                                                            meta.data.wiz_check = true;

                                                        } else if (data.stav == 1) {

                                                            //question
                                                            meta.data.wiz_kind = Gordic.Isl.GOperationResultKind.Error;
                                                            meta.data.wiz_txt_err = data.vysledek;
                                                        }

                                                        if (i == ixpArray.length) {
                                                            def.resolve(view)
                                                        }
                                                    });

                                            }
                                            else {
                                                i = i + 1;
                                                if (i == ixpArray.length) {
                                                    def.resolve(view)
                                                }
                                            } 
                                        }
                                    });

                                })
                                .fail(function (xhr, type, vobj) {

                                    view.getDataRows(true).forEach(function (meta) {
                                        vobj.handled = true;
                                        if (meta.data.ixp === x) {
                                            i = i + 1;
                                            meta.data.wiz_kind = Gordic.Isl.GOperationResultKind.Error;
                                            meta.data.wiz_txt_err = vobj.baseMessage;
                                            meta.data.wiz_check = false;
                                        }

                                        if (i == ixpArray.length) {
                                            def.resolve(view)
                                        }
                                    });


                                });
                        })
                        return def.promise();                     
                    },
                    nextActionName: "Storno",
                    nextAction: (model, data) => {

                        let def = $.Deferred();
                        let y = 0;

                        if (data.length == 0)
                            def.resolve(data);                    
                            

                        data.forEach(function (row) {                          
                                    that.isl.PokDoklad.storno(
                                        rq => {
                                            return {
                                                ixp: row.ixp,
                                                duvod: model.reason,
                                                datumOdparovani: row.wiz_datum!,
                                                kontorlovatRok: true

                                            }
                                        })
                                        .get()
                                        .done(function () {
                                            row.wiz_kind = Gordic.Isl.GOperationResultKind.Success;
                                            row.wiz_txt_err = "Doklad byl úspěšně stornován!";
                                        })
                                        .fail(function (xhr, type, vobj) {
                                            if (type === "exception") {
                                                if (vobj.baseType === "Gordic.General.GHplValidationException") {
                                                    vobj.handled = true;
                                                    row.wiz_kind = Gordic.Isl.GOperationResultKind.Error;
                                                    row.wiz_txt_err = vobj.baseMessage;

                                                }
                                                else if (vobj.data.member == "kontorlovatRok") {
                                                    vobj.handled = true;
                                                    //row.stavU = 2;
                                                    //row.vysledekU = vobj.baseMessage;
                                                    //question stav??
                                                    row.wiz_kind = Gordic.Isl.GOperationResultKind.Error;
                                                    row.wiz_txt_err = vobj.baseMessage;
                                                }
                                                else {
                                                    vobj.handled = true;
                                                    row.wiz_kind = Gordic.Isl.GOperationResultKind.Error;
                                                    row.wiz_txt_err = vobj.baseMessage;

                                                }
                                            }
                                        })
                                        .always(function () {
                                            y = y + 1;

                                            if (y == data.length) {
                                                def.resolve(data)
                                            }
                                        });
                               
                                });
                        
                        return def.promise();
                    
                    },
                },                
                lastStep:
                {
                    title: "Výsledek",
                    gridTabTitle: "Seznam stornovaných pokladních dokladů",
                    description: "Výsledek hromadného storna"
                },
                completeDelegate: (view) => {

                    that.close(true);
                },
                cancelDelegate: () => {
                    that.close(false);
                },
            }, { title: "Hromadné storno pokladních dokladů"   });

        }



         


        


    }


}


